import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"事件 API","description":"","frontmatter":{},"headers":[],"relativePath":"modules/gem/events.md","filePath":"modules/gem/events.md","lastUpdated":0}`),a={name:`modules/gem/events.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="事件-api" tabindex="-1">事件 API <a class="header-anchor" href="#事件-api" aria-label="Permalink to “事件 API”">​</a></h1><p>Gem 事件位于 <code>emaki.jiuwu.craft.gem.api.event</code>. 线程与派发契约: 所有事件同步发布在 actor owner thread; 公开 operations 在错误线程调用时直接拒绝, runtime 内部入口在无法取得 ownership 时不派发 pre 事件, 仍继续既定流程</p><table tabindex="0"><thead><tr><th>事件</th><th>触发时机</th><th>Cancellable</th><th>可修改字段</th><th>取消/结果效果</th><th>路径与 operationId</th></tr></thead><tbody><tr><td><code>GemInlayEvent</code></td><td>校验后, 开始扣费或摇点前</td><td>是</td><td><code>successChance</code>, clamp 0–100</td><td>停止镶嵌</td><td>service/API/GUI 等镶嵌路径; 生成 <code>operationId</code></td></tr><tr><td><code>GemExtractEvent</code></td><td>校验后, 扣费与移除前</td><td>是</td><td>无</td><td>停止拆卸</td><td>direct/API 与 held-item/GUI service 路径; 生成 <code>operationId</code></td></tr><tr><td><code>GemSocketOpenEvent</code></td><td>槽位与 opener 校验后, 开孔与消耗前</td><td>是</td><td>无</td><td>停止开孔和 opener 消耗</td><td>socket opener 的 direct/GUI 路径; 包含 <code>operationId</code></td></tr><tr><td><code>GemInlayCompletedEvent</code></td><td>success actions 完成且 journal 到达终态后; 已完成补偿的失败也可发</td><td>否</td><td>无</td><td>post, 不可回滚</td><td>与 pre 事件共享 <code>operationId</code>; <code>successful=false</code> 时读取 <code>reasonKey</code></td></tr><tr><td><code>GemExtractCompletedEvent</code></td><td>状态提交, success actions 完成且 journal <code>COMPLETED</code> 后</td><td>否</td><td>无</td><td>post, 不可回滚</td><td>API/direct/held-item 等实际 commit 路径, 与 pre 事件共享 <code>operationId</code></td></tr></tbody></table><p>Completed 事件的触发时机不是&quot;方法返回新装备时立即触发&quot;: 事务先返回或提交状态, 再等待 action stage 与持久 journal 到达终态. 若 actor 已离线或 owner scheduler 退役, runtime 记录该情况并跳过 completed event. 两个 completed 事件均不实现 Cancellable</p>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};